import pytest
from jsonschema import validate

# Test data and expected schema
PET_SCHEMA = {
    "type": "object",
    "properties": {
        "id": {"type": "integer"},
        "name": {"type": "string"},
        "category": {
            "type": "object",
            "properties": {
                "id": {"type": "integer"},
                "name": {"type": "string"}
            }
        },
        "photoUrls": {
            "type": "array",
            "items": {"type": "string"}
        },
        "tags": {
            "type": "array",
            "items": {
                "type": "object",
                "properties": {
                    "id": {"type": "integer"},
                    "name": {"type": "string"}
                }
            }
        },
        "status": {
            "type": "string",
            "enum": ["available", "pending", "sold"]
        }
    },
    "required": ["name", "photoUrls"]
}

@pytest.mark.parametrize("pet_id, expected_status", [
    (10, 200),
    (0, 400),
    (999999, 404)
])
def test_get_pet_by_id(api_client, valid_api_key, pet_id, expected_status):
    """Test GET /pet/{petId} endpoint with various pet IDs."""
    headers = {"api_key": valid_api_key}
    response = api_client.get(f"pet/{pet_id}", headers=headers)
    assert response.status_code == expected_status

    if response.status_code == 200:
        validate(instance=response.json(), schema=PET_SCHEMA)

def test_get_pet_by_id_invalid_key(api_client, invalid_api_key):
    """Test GET /pet/{petId} with invalid API key."""
    headers = {"api_key": invalid_api_key}
    response = api_client.get("pet/10", headers=headers)
    assert response.status_code == 403

def test_get_pet_by_id_no_auth(api_client):
    """Test GET /pet/{petId} without authentication."""
    response = api_client.get("pet/10")
    assert response.status_code == 401

